-- A catalog-scoped CD layout owns its measured graph. Exact generated CUEs require a real ordinary original;
-- mismatching descriptors retain their actual identity without making a preservation claim.
CREATE TABLE romd."CatalogCdLayoutBindings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Revision" uuid NOT NULL UNIQUE CHECK ("Revision" <> '00000000-0000-0000-0000-000000000000'),
    "CatalogFileId" integer NOT NULL UNIQUE REFERENCES romd."CatalogReleaseFiles" ("Id") ON DELETE CASCADE,
    "CatalogReleaseId" integer NOT NULL REFERENCES romd."CatalogReleases" ("Id") ON DELETE CASCADE,
    "CatalogFingerprint" varchar(120) NOT NULL CHECK (btrim("CatalogFingerprint") <> ''),
    "RequirementFingerprint" varchar(120) NOT NULL CHECK (btrim("RequirementFingerprint") <> ''),
    "Path" varchar(240) NOT NULL,
    "ExpectedSize" bigint NOT NULL CHECK ("ExpectedSize" BETWEEN 1 AND 65536),
    "ExpectedSha1" bytea NOT NULL CHECK (octet_length("ExpectedSha1") = 20 AND "ExpectedSha1" <> decode(repeat('00',20),'hex')),
    "ExpectedMd5" bytea NOT NULL CHECK (octet_length("ExpectedMd5") = 16 AND "ExpectedMd5" <> decode(repeat('00',16),'hex')),
    "ExpectedCrc32" bytea NOT NULL CHECK (octet_length("ExpectedCrc32") = 4),
    "RepresentationId" integer NOT NULL,
    "MemberOrdinal" integer NOT NULL,
    "GeneratorProfile" varchar(128) NOT NULL CHECK (btrim("GeneratorProfile") <> '' AND "GeneratorProfile" !~ '[[:cntrl:]]'),
    "CreatedAtUtcTicks" bigint NOT NULL CHECK ("CreatedAtUtcTicks" BETWEEN 0 AND 3155378975999999999),
    FOREIGN KEY ("RepresentationId","MemberOrdinal") REFERENCES romd."ReconstructionMembers" ("RepresentationId","Ordinal") ON DELETE RESTRICT
);
CREATE INDEX "IX_CatalogCdLayoutBindings_RepresentationId" ON romd."CatalogCdLayoutBindings" ("RepresentationId");

-- All catalog writers use this fence. Callers acquire the scope before creating/locking logical outputs.
CREATE FUNCTION romd.guard_catalog_cd_layout_binding() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $body$
DECLARE representation_id integer; release_id integer;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'Catalog CD layout provenance is immutable; withdraw an exact revision before replacement' USING ERRCODE = '23514';
    END IF;
    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION 'Catalog CD layout publication requires ReadCommitted authority' USING ERRCODE = '23514';
    END IF;
    representation_id := CASE WHEN TG_OP = 'DELETE' THEN OLD."RepresentationId" ELSE NEW."RepresentationId" END;
    release_id := CASE WHEN TG_OP = 'DELETE' THEN OLD."CatalogReleaseId" ELSE NEW."CatalogReleaseId" END;
    PERFORM pg_advisory_xact_lock(hashtext('romd.catalog-topology'));
    PERFORM 1 FROM romd."CatalogReleases" WHERE "Id" = release_id FOR NO KEY UPDATE;
    PERFORM 1 FROM romd."Roms" WHERE "Id" IN (SELECT "RomId" FROM romd."RepresentationOutputs" WHERE "RepresentationId" = representation_id)
        ORDER BY "Id" FOR NO KEY UPDATE;
    PERFORM pg_advisory_xact_lock(9415,representation_id);
    PERFORM 1 FROM romd."Representations" WHERE "Id" = representation_id FOR NO KEY UPDATE;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    PERFORM 1 FROM romd."Files" WHERE "Id" IN (
        SELECT "FileId" FROM romd."Representations" WHERE "Id" = representation_id UNION
        SELECT "StoredFileId" FROM romd."ReconstructionMembers" WHERE "RepresentationId" = representation_id)
        ORDER BY "Id" FOR NO KEY UPDATE;
    IF NOT EXISTS (SELECT 1 FROM romd."CatalogReleaseFiles" f JOIN romd."CatalogReleases" r ON r."Id" = f."CatalogReleaseId"
        WHERE f."Id" = NEW."CatalogFileId" AND r."Id" = release_id AND r."Fingerprint" = NEW."CatalogFingerprint" AND NOT r."HasTitleConflict" AND
            f."FileFingerprint" = NEW."RequirementFingerprint" AND f."Name" = NEW."Path" AND lower(right(f."Name",4)) = '.cue' AND NOT f."IsDisk" AND
            (f."Size",f."Sha1",f."Md5",f."Crc") = (NEW."ExpectedSize",NEW."ExpectedSha1",NEW."ExpectedMd5",NEW."ExpectedCrc32")) OR
        NOT EXISTS (SELECT 1 FROM romd."ReconstructionMembers" m JOIN romd."Files" f ON f."Id" = m."StoredFileId"
            WHERE m."RepresentationId" = representation_id AND m."Ordinal" = NEW."MemberOrdinal" AND m."StoredRole" = 'Cue' AND
                m."Path" = NEW."Path" AND m."ContentSize" <= 65536 AND f."Sha256" = m."ContentSha256" AND f."Size" = m."ContentSize") OR
        NOT EXISTS (SELECT 1 FROM romd."Verifications" WHERE "RepresentationId" = representation_id AND "DecoderRid" IS NOT NULL) OR
        (SELECT count(*) FROM romd."CatalogReleaseFiles" WHERE "CatalogReleaseId" = release_id) < 2 OR
        (SELECT count(*) FROM romd."CatalogReleaseFiles" WHERE "CatalogReleaseId" = release_id) <>
            1 + (SELECT count(*) FROM romd."RepresentationOutputs" WHERE "RepresentationId" = representation_id) OR
        (SELECT count(*) FROM romd."ReconstructionMembers" WHERE "RepresentationId" = representation_id AND "StoredFileId" IS NOT NULL) <> 1 OR
        EXISTS (SELECT 1 FROM romd."RepresentationOutputs" o JOIN romd."ReconstructionMembers" m
            ON m."RepresentationId" = o."RepresentationId" AND m."Ordinal" = o."MemberOrdinal"
            WHERE o."RepresentationId" = representation_id AND (o."RomId" IS NULL OR NOT EXISTS (
                SELECT 1 FROM romd."CatalogReleaseFiles" f WHERE f."CatalogReleaseId" = release_id AND f."Name" = m."Path" AND
                    lower(right(f."Name",4)) = '.bin' AND NOT f."IsDisk" AND
                    (f."Size",f."Sha1",f."Md5",f."Crc") = (o."ContentSize",o."Sha1",o."Md5",o."Crc32")))) THEN
        RAISE EXCEPTION 'Catalog CD layout binding requires the exact current catalog, complete measured BIN owners and a verified ordinary original for DAT-exact CUE bytes' USING ERRCODE = '23514';
    END IF;
    -- Ordinary-original ownership can change during media work; publication rechecks it.
    IF EXISTS (SELECT 1 FROM romd."ReconstructionMembers" m WHERE m."RepresentationId" = representation_id AND m."Ordinal" = NEW."MemberOrdinal" AND
            (m."ContentSize",m."Sha1",m."Md5",m."Crc32") = (NEW."ExpectedSize",NEW."ExpectedSha1",NEW."ExpectedMd5",NEW."ExpectedCrc32") AND NOT EXISTS (
                SELECT 1 FROM romd."Roms" original JOIN romd."RepresentationOutputs" output ON output."Id" = original."PreferredOutputId" AND output."RomId" = original."Id"
                JOIN romd."Representations" representation ON representation."Id" = output."RepresentationId"
                WHERE representation."Encoding" = 'Identity' AND EXISTS (SELECT 1 FROM romd."Verifications" WHERE "RepresentationId" = representation."Id") AND
                    (original."ContentSha256",original."ContentSize",original."Sha1",original."Md5",original."Crc32") =
                        (m."ContentSha256",m."ContentSize",m."Sha1",m."Md5",m."Crc32"))) THEN
        RAISE EXCEPTION 'The verified ordinary original for DAT-exact CUE bytes changed'
            USING ERRCODE = '23514', CONSTRAINT = 'catalog_cd_layout_original_changed';
    END IF;
    RETURN NEW;
END $body$;
CREATE TRIGGER "TR_CatalogCdLayoutBindings_Authority" BEFORE INSERT OR UPDATE OR DELETE ON romd."CatalogCdLayoutBindings"
    FOR EACH ROW EXECUTE FUNCTION romd.guard_catalog_cd_layout_binding();

CREATE FUNCTION romd.guard_catalog_cd_layout_representation_delete() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $body$
BEGIN
    IF EXISTS (SELECT 1 FROM romd."CatalogCdLayoutBindings" WHERE "RepresentationId" = OLD."Id") THEN
        RAISE EXCEPTION 'Catalog CD layout bindings retain their representation and every decoder measurement' USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
END $body$;
CREATE TRIGGER "TR_Representations_CatalogCdLayoutOwnership" BEFORE DELETE ON romd."Representations"
    FOR EACH ROW EXECUTE FUNCTION romd.guard_catalog_cd_layout_representation_delete();
REVOKE ALL ON FUNCTION romd.guard_catalog_cd_layout_binding(),romd.guard_catalog_cd_layout_representation_delete() FROM PUBLIC;

-- This is a current source projection, not a stored eligibility or preservation claim.
-- Both exact and derived CUE associations stay factual; ordinary-original priority belongs to delivery.
CREATE VIEW romd."CurrentCatalogCdLayoutBindings" AS
SELECT d.*,r."PlatformId" FROM romd."CatalogCdLayoutBindings" d
JOIN romd."CatalogReleases" r ON r."Id"=d."CatalogReleaseId"
JOIN romd."CatalogReleaseFiles" f ON f."Id"=d."CatalogFileId" AND f."CatalogReleaseId"=r."Id"
JOIN romd."ReconstructionMembers" m ON m."RepresentationId"=d."RepresentationId" AND m."Ordinal"=d."MemberOrdinal"
JOIN romd."Files" physical ON physical."Id"=m."StoredFileId"
WHERE NOT f."IsDisk" AND r."Fingerprint"=d."CatalogFingerprint" AND NOT r."HasTitleConflict" AND
    (f."FileFingerprint",f."Name",f."Size",f."Sha1",f."Md5",f."Crc") =
        (d."RequirementFingerprint",d."Path",d."ExpectedSize",d."ExpectedSha1",d."ExpectedMd5",d."ExpectedCrc32") AND
    m."StoredRole"='Cue' AND (physical."Sha256",physical."Size")=(m."ContentSha256",m."ContentSize") AND
    EXISTS (SELECT 1 FROM romd."Verifications" WHERE "RepresentationId"=d."RepresentationId" AND "DecoderRid" IS NOT NULL) AND
    (SELECT count(*) FROM romd."ReconstructionMembers" WHERE "RepresentationId"=d."RepresentationId" AND "StoredFileId" IS NOT NULL)=1 AND
    (SELECT count(*) FROM romd."CatalogReleaseFiles" WHERE "CatalogReleaseId"=r."Id")=
        1+(SELECT count(*) FROM romd."RepresentationOutputs" WHERE "RepresentationId"=d."RepresentationId") AND
    NOT EXISTS (SELECT 1 FROM romd."RepresentationOutputs" o JOIN romd."ReconstructionMembers" b
        ON b."RepresentationId"=o."RepresentationId" AND b."Ordinal"=o."MemberOrdinal"
        WHERE o."RepresentationId"=d."RepresentationId" AND (o."RomId" IS NULL OR NOT EXISTS (
            SELECT 1 FROM romd."CatalogReleaseFiles" bin WHERE bin."CatalogReleaseId"=r."Id" AND bin."Name"=b."Path" AND NOT bin."IsDisk" AND
                (bin."Size",bin."Sha1",bin."Md5",bin."Crc")=(o."ContentSize",o."Sha1",o."Md5",o."Crc32"))));
REVOKE ALL ON romd."CurrentCatalogCdLayoutBindings" FROM PUBLIC;
